import yaml,re
src=open('claude-dev-log-diary/day-017.md').read()
norm=lambda s: re.sub(r'\s+',' ',s).strip()
n=norm(src)
d=yaml.safe_load(open('.coordination/mining/v2/day-017.yaml'))
bad=[]
def chk(q,loc):
    if not q: return
    # split on ellipsis used to elide
    for part in re.split(r'\.\.\.', q):
        p=norm(part)
        if len(p)<15: continue
        if p not in n: bad.append((loc,p[:90]))
for s in ['philosophy','skill_rules','pairing_rules','failure_modes']:
    for it in d.get(s,[]):
        chk(it.get('quote'), it.get('loc') or it.get('evidence'))
for b in bad: print('MISSING:',b)
print('checked; missing count =',len(bad))
"
